mapper.sql:
WHERE S.DEL_YN = 'N'

  AND S.DCSN_DT >= #{searchFixFrom}


  AND S.DCSN_DT <= #{searchFixTo}


  AND S.ITPT_KIND_CD = #{searchItpt}


  AND S.CASE_KIND_CD = #{searchCaseKind}


  AND S.RSLT_KIND_CD = #{searchRslt}


  AND S.CASE_YEAR = #{searchCaseYear}


  AND S.CASE_SIGN_CD = #{searchCaseSign}


  AND S.CASE_SERIAL LIKE '%' || #{searchCaseSerial} || '%'

mapper.select:
SELECT S.SUIT_ID AS suitId, S.FIRST_SUIT_ID AS firstSuitId, S.CASE_KIND_CD AS caseKindCd, CK.CODE_NM AS caseKindNm, S.INSTANCE_CD AS instanceCd, IC.CODE_NM AS instanceNm, S.COURT_NM AS courtNm, S.CASE_NO AS caseNo, S.CASE_NM AS caseNm, S.SUIT_AMT AS suitAmt, CASE WHEN LENGTH(S.FR_DT) = 8 THEN SUBSTR(S.FR_DT, 1, 4) || '-' || SUBSTR(S.FR_DT, 5, 2) || '-' || SUBSTR(S.FR_DT, 7, 2) ELSE S.FR_DT END AS frDt, CASE WHEN LENGTH(S.STC_DT) = 8 THEN SUBSTR(S.STC_DT, 1, 4) || '-' || SUBSTR(S.STC_DT, 5, 2) || '-' || SUBSTR(S.STC_DT, 7, 2) ELSE S.STC_DT END AS stcDt, S.DCSN_DT AS dcsnDt, S.RSLT_KIND_CD AS rsltKindCd, NVL(S.RSLT_KIND_NM, RS.CODE_NM) AS rsltDispNm, S.WIN_AMT AS winAmt, S.LOSE_AMT AS loseAmt, P.NM AS plaintiffNm, NVL(P.CNT, 0) AS plaintiffCnt, D.NM AS defendantNm, NVL(D.CNT, 0) AS defendantCnt, L.SUMMARY AS landSummary, NVL(L.CNT, 0) AS landCnt, G.LATEST_DESC AS progSummary FROM LAW_SUIT S LEFT OUTER JOIN COMTCCMMNDETAILCODE CK ON CK.CODE_ID = 'LAW_CASE_KIND' AND CK.CODE = S.CASE_KIND_CD LEFT OUTER JOIN COMTCCMMNDETAILCODE IC ON IC.CODE_ID = 'LAW_INSTANCE' AND IC.CODE = S.INSTANCE_CD LEFT OUTER JOIN COMTCCMMNDETAILCODE RS ON RS.CODE_ID = 'LAW_RESULT' AND RS.CODE = S.RSLT_KIND_CD
LEFT OUTER JOIN ( SELECT SUIT_ID, MAX(CASE WHEN RN = 1 THEN PARTY_NM END) NM, COUNT(*) CNT FROM ( SELECT SUIT_ID, PARTY_NM, ROW_NUMBER() OVER (PARTITION BY SUIT_ID ORDER BY SORT_ORDR, PARTY_ID) RN FROM LAW_SUIT_PARTY WHERE PARTY_TYPE = 'P' ) TP GROUP BY SUIT_ID ) P ON P.SUIT_ID = S.SUIT_ID LEFT OUTER JOIN ( SELECT SUIT_ID, MAX(CASE WHEN RN = 1 THEN PARTY_NM END) NM, COUNT(*) CNT FROM ( SELECT SUIT_ID, PARTY_NM, ROW_NUMBER() OVER (PARTITION BY SUIT_ID ORDER BY SORT_ORDR, PARTY_ID) RN FROM LAW_SUIT_PARTY WHERE PARTY_TYPE = 'D' ) TD GROUP BY SUIT_ID ) D ON D.SUIT_ID = S.SUIT_ID LEFT OUTER JOIN ( SELECT SUIT_ID, MAX(CASE WHEN RN = 1 THEN SUMMARY1 END) SUMMARY, COUNT(*) CNT FROM ( SELECT SUIT_ID, TRIM(IFNULL(LOCATION,'') || ' ' || IFNULL(JIBUN,'')) SUMMARY1, ROW_NUMBER() OVER (PARTITION BY SUIT_ID ORDER BY SORT_ORDR, LAND_ID) RN FROM LAW_SUIT_LAND ) TL GROUP BY SUIT_ID ) L ON L.SUIT_ID = S.SUIT_ID LEFT OUTER JOIN ( SELECT SUIT_ID, MAX(CASE WHEN RN = 1 THEN PROG_DESC END) LATEST_DESC FROM ( SELECT SUIT_ID, PROG_DESC, ROW_NUMBER() OVER (PARTITION BY SUIT_ID ORDER BY PROG_DT DESC, PROG_ID DESC) RN FROM LAW_SUIT_PROG ) TG GROUP BY SUIT_ID ) G ON G.SUIT_ID = S.SUIT_ID
ORDER BY S.SUIT_ID DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

mapper.update:
UPDATE LAW_SUIT
   SET DEL_YN      = 'Y',
       UPD_USER_ID = #{updUserId},
       UPD_DT      = #{updDt}
 WHERE SUIT_ID = #{suitId}

mapper.insert:
INSERT INTO LAW_SUIT_PARTY (
	PARTY_ID, SUIT_ID, PARTY_TYPE, PARTY_NM, BIRTH, JUMIN_ENC, AGENT_NM, SORT_ORDR, REG_DT
) VALUES (
	#{partyId}, #{suitId}, #{partyType}, #{partyNm}, #{birth}, #{juminEnc}, #{agentNm}, #{sortOrdr},
	TO_CHAR(SYSDATE(), 'YYYYMMDDHH24MISS')
)

INSERT INTO LAW_SUIT_LAND (
	LAND_ID, SUIT_ID, LOCATION, JIBUN, SORT_ORDR, REG_DT
) VALUES (
	#{landId}, #{suitId}, #{location}, #{jibun}, #{sortOrdr}, TO_CHAR(SYSDATE(), 'YYYYMMDDHH24MISS')
)

INSERT INTO LAW_SUIT_STAFF (
	STAFF_ID, SUIT_ID, ORGNZT_ID, STAFF_NM, ASSIGN_DT, SORT_ORDR, REG_DT
) VALUES (
	#{staffId}, #{suitId}, #{orgnztId}, #{staffNm}, #{assignDt}, #{sortOrdr}, TO_CHAR(SYSDATE(), 'YYYYMMDDHH24MISS')
)

mapper.select:
SELECT NVL(MAX(HIST_SEQ), 0)
  FROM LAW_SUIT_RSLT_HIST
 WHERE SUIT_ID = #{suitId}

mapper.insert:
INSERT INTO LAW_SUIT_RSLT_HIST (
	HIST_ID, SUIT_ID, HIST_SEQ, RSLT_KIND_CD, RSLT_KIND_NM, END_DT, HIST_DESC, REG_USER_ID, REG_DT
) VALUES (
	#{histId}, #{suitId}, #{histSeq}, #{rsltKindCd}, #{rsltKindNm}, #{endDt}, #{histDesc}, #{regUserId}, #{regDt}
)
